mapper.select:
select distinct ct.id as id, ct.template_id as templateId, ct.company_dept_id as companyDeptId, ct.status as status, t.name as templateName, ct.calculation_cycle_start_date as cycleStart, ct.calculation_cycle_end_date as cycleEnd, ct.calculation_end_time as finishedAt from emission_calculation_template ct left join emission_template t on t.id = ct.template_id inner join emission_calculation_node cn on cn.calculation_template_id = ct.id where ( cn.node_id = #{subjectNodeId} or exists ( select 1 from emission_node source_node where source_node.id = cn.node_id and source_node.source_node_id = #{subjectNodeId} )
) and (select count(*) from report_dept_subject s join sys_carbon_company c on c.dept_id=s.dept_id where s.subject_node_id=#{subjectNodeId}) = 1 and t.template_type = 2
and ct.calculation_cycle_start_date <= #{periodEnd} and ct.calculation_cycle_end_date >= #{periodStart}
order by ct.calculation_end_time desc

select ct.id, ct.template_id as templateId, ct.company_dept_id as companyDeptId, ct.status, t.name as templateName, ct.calculation_cycle_start_date as cycleStart, ct.calculation_cycle_end_date as cycleEnd, ct.calculation_end_time as finishedAt from emission_calculation_template ct inner join emission_template t on t.id = ct.template_id where ct.company_dept_id = #{companyDeptId} and ct.status = 2 and t.template_type = 2
and ct.calculation_cycle_start_date <= #{periodEnd} and ct.calculation_cycle_end_date >= #{periodStart}
order by ct.calculation_end_time desc, ct.id desc
